/**
 * Client-side symbol filtering for the navbar type-ahead, with AND-based
 * multi-term matching.
 *
 * Pure functions, no Vue dependency, so behavior is unit-testable with Jest.
 * NavFilter.vue consumes this once a query reaches the shared minimum length
 * (see sidebar-filter.ts) — matching is entirely
 * in-memory, no network round-trip.
 */

/** Construct level of a symbol, as classified by docgen. */
export type ConstructLevelTag = 'L1' | 'L2' | 'L3';

/** One entry of the symbol index generated by docgen. */
export interface SymbolEntry {
  readonly name: string;
  readonly kind: string;
  readonly link: string;
  readonly service: string;
  /** Present (true) when the owning module is experimental (alpha); absent for stable modules. */
  readonly experimental?: boolean;
  /** Construct level, when the symbol is a leveled construct; absent for everything else. */
  readonly level?: ConstructLevelTag;
}

/**
 * Query terms that name a construct level rather than a symbol. These three are the whole vocabulary: `l2` filters
 * to L2 constructs instead of matching its two characters against names and services.
 */
const LEVEL_TERMS: ReadonlyMap<string, ConstructLevelTag> = new Map([
  ['l1', 'L1'],
  ['l2', 'L2'],
  ['l3', 'L3'],
]);

/** The construct level a query term names, or undefined when the term is an ordinary one. */
function levelTerm(term: string): ConstructLevelTag | undefined {
  return LEVEL_TERMS.get(term.toLowerCase());
}

const RANK_PREFIX = 0;
const RANK_WORD = 1;
const RANK_SUBSTRING = 2;
/** The term matched the entry's service/section, not the symbol name. */
const RANK_CONTEXT = 3;

/**
 * Split a query into lowercase whitespace-separated terms. Repeated whitespace
 * collapses away; a blank query yields no terms. Terms combine with AND.
 */
export function splitTerms(query: string): string[] {
  return query.toLowerCase().split(/\s+/).filter(Boolean);
}

/**
 * Match rank of a single term against a text (lower is better), or
 * undefined when it does not match. Word rank matches the start of a
 * camelCase/dot-separated segment (e.g. "bucket" -> `s3.Bucket`).
 * Case-insensitive on both sides.
 */
export function termRank(text: string, term: string): number | undefined {
  const haystack = text.toLowerCase();
  const needle = term.toLowerCase();
  const index = haystack.indexOf(needle);
  if (index < 0) {
    return undefined;
  }
  if (index === 0) {
    return RANK_PREFIX;
  }
  const before = text[index - 1];
  const at = text[index];
  if (before === '.' || before === '_' || (at >= 'A' && at <= 'Z')) {
    return RANK_WORD;
  }
  return RANK_SUBSTRING;
}

/**
 * Match rank of a name against a whole query (lower is better), or undefined when
 * it does not match. The query splits into whitespace-separated terms which must
 * all match, anywhere in the name, in any order. The rank sums the per-term
 * ranks, so names matching more precisely sort first.
 */
export function matchRank(name: string, query: string): number | undefined {
  const terms = splitTerms(query);
  if (terms.length === 0) {
    return undefined;
  }
  let total = 0;
  for (const term of terms) {
    const rank = termRank(name, term);
    if (rank === undefined) {
      return undefined;
    }
    total += rank;
  }
  return total;
}

/**
 * Rank of an entry against all terms (AND), or undefined when any term is unsatisfied.
 *
 * A term is satisfied by the symbol name, by a level qualifier ({@link LEVEL_TERMS}), or by the service. The latter
 * two are qualifiers rather than identifiers, so they are free once some other term matches the name: `s3 bucket`
 * then surfaces `Bucket` (S3) ahead of an `S3BucketOrigin` whose name happens to carry both terms, and `l2 bucket`
 * ranks by the name term alone among L2 constructs. When no term matches the name every qualifier pays
 * {@link RANK_CONTEXT}, keeping those below any name match.
 *
 * A level term is satisfied ONLY by the entry's level, never by its name or service, so an entry without a level
 * cannot match one.
 */
function entryRank(entry: SymbolEntry, terms: readonly string[]): number | undefined {
  let total = 0;
  let qualifiers = 0;
  let namedMatch = false;
  for (const term of terms) {
    const level = levelTerm(term);
    if (level !== undefined) {
      if (entry.level !== level) {
        return undefined;
      }
      qualifiers += 1;
      continue;
    }
    const nameRank = termRank(entry.name, term);
    if (nameRank !== undefined) {
      total += nameRank;
      namedMatch = true;
      continue;
    }
    if (termRank(entry.service, term) !== undefined) {
      qualifiers += 1;
      continue;
    }
    return undefined;
  }
  return namedMatch ? total : qualifiers * RANK_CONTEXT;
}

/**
 * Filter symbols by query, best matches first. Whitespace-separated terms combine
 * with AND: every term must match the symbol's name or, failing that, its
 * service — except `l1`/`l2`/`l3`, which constrain the construct level instead and
 * match nothing else, so `l2 bucket` returns L2 constructs named `bucket` and a
 * bare `l2` returns every L2 construct. Ranking sums the per-term name ranks
 * (prefix, then word-boundary, then substring); a term carried by the service or a
 * level alone is free beside a name match and costs {@link RANK_CONTEXT} when
 * nothing matched the name. Ties break in favor of
 * a stable module over an experimental (alpha) one, then on shorter name, then
 * alphabetically — so `function` opens an `aws-cdk-lib` `Function` rather than an
 * alpha module's, while a query that names only the alpha symbol, or names it more
 * precisely, still reaches it. Two stable symbols that tie on all of the above keep
 * the index order. Empty/blank queries return no results.
 */
export function filterSymbols(
  symbols: readonly SymbolEntry[],
  query: string,
  limit: number = 20,
): SymbolEntry[] {
  const terms = splitTerms(query);
  if (terms.length === 0) {
    return [];
  }
  const ranked: { entry: SymbolEntry; rank: number }[] = [];
  for (const entry of symbols) {
    const rank = entryRank(entry, terms);
    if (rank !== undefined) {
      ranked.push({ entry, rank });
    }
  }
  ranked.sort(
    (a, b) =>
      a.rank - b.rank
      || Number(a.entry.experimental ?? false) - Number(b.entry.experimental ?? false)
      || a.entry.name.length - b.entry.name.length
      || a.entry.name.localeCompare(b.entry.name),
  );
  return ranked.slice(0, limit).map((r) => r.entry);
}
